class Payment extends Agreement { protected double paymentAmount; protected String paymentDate; public Payment(int id, String agencyName, String location, String phoneNumber, String agentName, String emailAgent, String licenseNumber, String propertyCode, String propertyType, double price, String sellerName, String contactNumber, String buyerName, String email, String agreementDate, String terms, double paymentAmount, String paymentDate){ super(id, agencyName, location, phoneNumber, agentName, emailAgent, licenseNumber, propertyCode, propertyType, price, sellerName, contactNumber, buyerName, email, agreementDate, terms); setPaymentAmount(paymentAmount); this.paymentDate = paymentDate;} public void setPaymentAmount(double p){ this.paymentAmount = Math.max(0.01, p);} }
